scripts.factorial_mod:
def solve(inputs: dict) -> float:
    N = inputs['N']
    MOD = inputs['MOD']

    # Compute N! mod MOD
    result = 1
    for i in range(1, N + 1):
        result = (result * i) % MOD

    return float(result)

