def solve(inputs: dict) -> float:
    from math import gcd

    remainders = inputs['REMAINDERS']
    moduli = inputs['MODULI']

    # Extended GCD for CRT
    def extended_gcd(a, b):
        if a == 0:
            return b, 0, 1
        gcd_val, x1, y1 = extended_gcd(b % a, a)
        x = y1 - (b // a) * x1
        y = x1
        return gcd_val, x, y

    def mod_inverse(a, m):
        gcd_val, x, _ = extended_gcd(a % m, m)
        if gcd_val != 1:
            return None
        return (x % m + m) % m

    # Use standard CRT for coprime moduli
    # First check if moduli are pairwise coprime
    all_coprime = True
    for i in range(len(moduli)):
        for j in range(i+1, len(moduli)):
            if gcd(moduli[i], moduli[j]) != 1:
                all_coprime = False
                break

    if all_coprime:
        # Standard CRT
        M = 1
        for m in moduli:
            M *= m

        x = 0
        for i in range(len(moduli)):
            Mi = M // moduli[i]
            yi = mod_inverse(Mi, moduli[i])
            x += remainders[i] * Mi * yi

        return float(x % M)
    else:
        # Handle non-coprime case step by step
        x = remainders[0]
        M = moduli[0]

        for i in range(1, len(remainders)):
            r = remainders[i]
            m = moduli[i]

            diff = (r - x) % m
            M_mod_m = M % m
            M_inv = mod_inverse(M_mod_m, m)

            if M_inv is None:
                g = gcd(M, m)
                if diff % g != 0:
                    return -1
                k = (diff // g) * mod_inverse(M // g, m // g)
            else:
                k = (diff * M_inv) % m

            x = x + k * M
            M = M * m // gcd(M, m)

        return float(x)

